#!/usr/bin/env python3
"""CSV Insights — a dependency-free command-line CSV analytics tool."""

from __future__ import annotations

import csv
import json
import sys
from decimal import Decimal, InvalidOperation
from typing import Sequence


class CliError(Exception):
    """Raised for any user-facing error; the message is printed to stderr."""


def _eprint(msg: str) -> None:
    print(msg, file=sys.stderr)


def _read_csv(path: str) -> tuple[list[str], list[list[str]]]:
    """Read a CSV file, returning (header, rows)."""
    try:
        f = open(path, "r", newline="", encoding="utf-8")
    except OSError as exc:
        raise CliError(f"{path}: cannot open file ({exc})")
    with f:
        reader = csv.reader(f)
        try:
            header = next(reader)
        except StopIteration:
            raise CliError(f"{path}: file is empty (no header row)")
        if not any(cell.strip() for cell in header):
            raise CliError(f"{path}: header row is empty")
        if len(header) != len(set(header)):
            dups = sorted({c for c in header if header.count(c) > 1})
            raise CliError(f"{path}: duplicate header(s): {', '.join(dups)}")
        rows: list[list[str]] = []
        for lineno, row in enumerate(reader, start=2):
            if len(row) == 0:
                continue
            if len(row) != len(header):
                raise CliError(
                    f"{path}: line {lineno}: expected {len(header)} fields, got {len(row)}"
                )
            rows.append(row)
    return header, rows


def _column_index(header: list[str], name: str) -> int:
    try:
        return header.index(name)
    except ValueError:
        raise CliError(f"unknown column: {name!r}")


def _parse_filter(spec: str, header: list[str]) -> tuple[str, str]:
    if "=" not in spec:
        raise CliError(f"malformed filter (expected COLUMN=VALUE): {spec!r}")
    col, value = spec.split("=", 1)
    if col not in header:
        raise CliError(f"unknown column in filter: {col!r}")
    return col, value


def _apply_filters(
    header: list[str],
    rows: list[list[str]],
    filters: Sequence[tuple[str, str]],
) -> list[list[str]]:
    out = rows
    for col, value in filters:
        idx = _column_index(header, col)
        out = [r for r in out if r[idx] == value]
    return out


def _to_decimal(value: str, row_num: int, col_name: str) -> Decimal:
    try:
        return Decimal(value)
    except (InvalidOperation, ValueError):
        raise CliError(
            f"non-numeric value in column {col_name!r}, row {row_num}: {value!r}"
        )


def _format_decimal(d: Decimal) -> str:
    s = format(d, "f")
    if "." in s:
        s = s.rstrip("0").rstrip(".")
    if s == "-0":
        s = "0"
    return s


def _aggregate(
    header: list[str],
    rows: list[list[str]],
    group_by: str,
    sum_cols: list[str],
    avg_cols: list[str],
) -> list[dict[str, str]]:
    gidx = _column_index(header, group_by)
    sum_idxs = [(c, _column_index(header, c)) for c in sum_cols]
    avg_idxs = [(c, _column_index(header, c)) for c in avg_cols]

    groups: dict[str, list[list[str]]] = {}
    for r in rows:
        groups.setdefault(r[gidx], []).append(r)

    result: list[dict[str, str]] = []
    for gval in sorted(groups):
        members = groups[gval]
        entry: dict[str, str] = {group_by: gval}
        for col, idx in sum_idxs:
            total = Decimal(0)
            for rn, r in enumerate(members, start=1):
                cell = r[idx].strip()
                if cell == "":
                    raise CliError(
                        f"empty numeric value in column {col!r}, group {gval!r}, row {rn}"
                    )
                total += _to_decimal(cell, rn, col)
            entry[f"sum_{col}"] = _format_decimal(total)
        for col, idx in avg_idxs:
            total = Decimal(0)
            for rn, r in enumerate(members, start=1):
                cell = r[idx].strip()
                if cell == "":
                    raise CliError(
                        f"empty numeric value in column {col!r}, group {gval!r}, row {rn}"
                    )
                total += _to_decimal(cell, rn, col)
            count = Decimal(len(members))
            entry[f"avg_{col}"] = _format_decimal(total / count)
        result.append(entry)
    return result


def _emit_json(records: list[dict[str, str]]) -> str:
    return json.dumps(records, indent=2)


def _emit_csv(records: list[dict[str, str]]) -> str:
    if not records:
        return ""
    fieldnames = list(records[0].keys())
    buf: list[str] = []
    out = csv.writer(buf, lineterminator="\n", quoting=csv.QUOTE_MINIMAL)
    out.writerow(fieldnames)
    for r in records:
        out.writerow([r.get(f, "") for f in fieldnames])
    return "\n".join(buf)


def _parse_args(argv: list[str]) -> dict:
    if not argv:
        raise CliError("usage: python3 main.py INPUT.csv [--where COLUMN=VALUE ...] "
                       "[--group-by COLUMN] [--sum COLUMN] [--avg COLUMN] [--output json|csv]")
    opts = {
        "input": None,
        "where": [],
        "group-by": None,
        "sum": [],
        "avg": [],
        "output": "json",
    }
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == "--where":
            i += 1
            if i >= len(argv):
                raise CliError("--where requires a value")
            opts["where"].append(argv[i])
        elif a == "--group-by":
            i += 1
            if i >= len(argv):
                raise CliError("--group-by requires a value")
            if opts["group-by"] is not None:
                raise CliError("--group-by specified multiple times")
            opts["group-by"] = argv[i]
        elif a == "--sum":
            i += 1
            if i >= len(argv):
                raise CliError("--sum requires a value")
            opts["sum"].append(argv[i])
        elif a == "--avg":
            i += 1
            if i >= len(argv):
                raise CliError("--avg requires a value")
            opts["avg"].append(argv[i])
        elif a == "--output":
            i += 1
            if i >= len(argv):
                raise CliError("--output requires a value")
            if argv[i] not in ("json", "csv"):
                raise CliError(f"invalid --output value (expected json|csv): {argv[i]!r}")
            opts["output"] = argv[i]
        elif a.startswith("--"):
            raise CliError(f"unknown option: {a}")
        else:
            if opts["input"] is not None:
                raise CliError(f"unexpected extra argument: {a}")
            opts["input"] = a
        i += 1
    if opts["input"] is None:
        raise CliError("no input file specified")
    if (opts["sum"] or opts["avg"]) and not opts["group-by"]:
        raise CliError("--sum/--avg requires --group-by")
    return opts


def run(argv: list[str]) -> str:
    opts = _parse_args(argv)
    header, rows = _read_csv(opts["input"])
    filters = [_parse_filter(f, header) for f in opts["where"]]
    rows = _apply_filters(header, rows, filters)

    if opts["group-by"]:
        records = _aggregate(
            header, rows, opts["group-by"], opts["sum"], opts["avg"]
        )
    else:
        records = [dict(zip(header, r)) for r in rows]

    if opts["output"] == "json":
        return _emit_json(records)
    return _emit_csv(records)


def main() -> int:
    try:
        output = run(sys.argv[1:])
    except CliError as exc:
        _eprint(str(exc))
        return 1
    sys.stdout.write(output)
    if output and not output.endswith("\n"):
        sys.stdout.write("\n")
    return 0


if __name__ == "__main__":
    sys.exit(main())

